const policyButton=document.getElementById('policy-language');
let policyLanguage=new URLSearchParams(location.search).get('lang')==='en'?'en':'zh';
function renderPolicy(){document.documentElement.lang=policyLanguage==='en'?'en':'zh-CN';document.querySelectorAll('[data-policy-lang]').forEach(el=>el.hidden=el.dataset.policyLang!==policyLanguage);document.querySelectorAll('[data-zh][data-en]').forEach(el=>el.textContent=el.dataset[policyLanguage]);policyButton.textContent=policyLanguage==='en'?'中文':'English';document.title=document.body.dataset.page==='about'?(policyLanguage==='en'?'About Along the Way — Along the Way':'关于沿线 — 沿线'):(policyLanguage==='en'?'Reuse and attribution — Along the Way':'引用与使用说明 — 沿线');document.querySelectorAll('a[href]').forEach(a=>{const href=a.getAttribute('href');if(/^(about|reuse)\.html/.test(href))a.href=href.split('?')[0]+'?lang='+policyLanguage;if(href==='./'||href.startsWith('./#'))a.href='./#view=world&lang='+policyLanguage;});}
policyButton.addEventListener('click',()=>{policyLanguage=policyLanguage==='en'?'zh':'en';renderPolicy();});renderPolicy();
